<?php
session_start();if(($_SESSION['role']??'')!=='admin'){header('Location: /authenication/login/login.php');exit;}require_once(__DIR__.'/../../../Database/db/db.php');$pdo=get_db();$start=$_GET['start']??date('Y-m-01');$end=$_GET['end']??date('Y-m-d');foreach(['start','end'] as $key){if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',${$key})){${$key}=$key==='start'?date('Y-m-01'):date('Y-m-d');}}$q=$pdo->prepare("SELECT currency,COUNT(*) AS count,SUM(final_amount) AS total FROM payments WHERE status='paid' AND DATE(COALESCE(paid_at,created_at)) BETWEEN ? AND ? GROUP BY currency ORDER BY currency");$q->execute([$start,$end]);$totals=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare("SELECT p.invoice_number,p.user_id,p.final_amount,p.currency,p.gateway,p.paid_at,p.created_at,u.username FROM payments p LEFT JOIN users u ON u.id=p.user_id WHERE p.status='paid' AND DATE(COALESCE(p.paid_at,p.created_at)) BETWEEN ? AND ? ORDER BY COALESCE(p.paid_at,p.created_at) DESC LIMIT 100");$q->execute([$start,$end]);$payments=$q->fetchAll(PDO::FETCH_ASSOC);$pageTitle='Financial reports';include(__DIR__.'/../../includes/header/header.php');include(__DIR__.'/../../includes/navbar/navbar.php');include(__DIR__.'/../../includes/sidebar/sidebar.php');
?>
<main class="main-content"><div class="container-fluid"><div class="page-heading"><div><span class="page-kicker">REPORTS</span><h1>Financial reports</h1><p>Paid transactions recorded in the selected date range.</p></div></div><section class="card border-0 mb-4"><div class="card-body"><form class="row g-3 align-items-end" method="get"><div class="col-sm-4"><label class="form-label">From</label><input class="form-control" type="date" name="start" value="<?=htmlspecialchars($start)?>"></div><div class="col-sm-4"><label class="form-label">Through</label><input class="form-control" type="date" name="end" value="<?=htmlspecialchars($end)?>"></div><div class="col-sm-4"><button class="btn btn-primary">Apply dates</button> <a class="btn btn-light" href="?">This month</a></div></form></div></section><div class="row g-3 mb-4"><?php if(!$totals):?><div class="col-12"><div class="alert alert-info">No paid transactions in this period.</div></div><?php endif;?><?php foreach($totals as $sum):?><div class="col-sm-6 col-xl-4"><div class="metric-card"><span class="metric-icon green"><i class="fa-solid fa-money-bill-wave"></i></span><span class="metric-label">Paid revenue · <?=htmlspecialchars($sum['currency'])?></span><strong><?=number_format((float)$sum['total'],2)?></strong><small><?=number_format((int)$sum['count'])?> successful payments</small></div></div><?php endforeach;?></div><section class="card border-0"><div class="table-toolbar"><div><h2 class="h5 mb-1">Transactions</h2><p class="text-muted small mb-0">Amounts remain grouped by currency above.</p></div><div class="table-search"><i class="fa-solid fa-magnifying-glass"></i><input data-table-search="paymentTable" placeholder="Search transactions" aria-label="Search transactions"></div></div><div class="table-responsive"><table class="table admin-table mb-0" id="paymentTable" data-admin-sort><thead><tr><th data-sort>Invoice</th><th data-sort>Account</th><th data-sort>Amount</th><th data-sort>Gateway</th><th data-sort>Paid</th></tr></thead><tbody><?php if(!$payments):?><tr><td colspan="5"><div class="empty-state"><strong>No transactions found</strong></div></td></tr><?php endif;?><?php foreach($payments as $payment):?><tr><td><?=htmlspecialchars($payment['invoice_number'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($payment['username']??('User #'.$payment['user_id']),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($payment['currency'])?> <?=number_format((float)$payment['final_amount'],2)?></td><td><?=htmlspecialchars($payment['gateway'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars(date('M j, Y',strtotime($payment['paid_at']??$payment['created_at'])),ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;?></tbody></table></div></section></div></main><?php include(__DIR__.'/../../includes/footer/footer.php');?>
